// Agent Playground — test any agent with a prompt (SSE streaming)
app.post('/api/playground/run', rateLimit('heavy'), (req, res) => {
  const { agentName, prompt: userPrompt, customInstructions, timeoutMs } = req.body;
  if (!userPrompt) return res.status(400).json({ error: 'Prompt is required' });

  res.setTimeout(0);
  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');

  const send = (data) => res.write(`data: ${JSON.stringify(data)}\n\n`);

  // Load agent instructions
  let instructions = '';
  if (agentName) {
    const agentContentMap = {};
    const globalAgentsDir = path.join(CLAUDE_DIR, 'agents');
    if (fs.existsSync(globalAgentsDir)) {
      for (const file of fs.readdirSync(globalAgentsDir).filter(f => f.endsWith('.md'))) {
        const content = fs.readFileSync(path.join(globalAgentsDir, file), 'utf-8');
        const nameMatch = content.match(/^name:\s*(.+)$/m);
        const key = nameMatch ? nameMatch[1].trim() : file.replace('.md', '');
        agentContentMap[key] = content;
        agentContentMap[file.replace('.md', '')] = content;
      }
    }
    // Also check project agents
    const config = loadConfig();
    const projects = discoverProjects(config.projectDirs);
    for (const p of projects) {
      for (const a of (p.agents || [])) {
        agentContentMap[a.name] = a.body || a.raw;
        agentContentMap[a.filename] = a.body || a.raw;
      }
    }
    instructions = agentContentMap[agentName] || '';

    // Agent not found — warn the user
    if (!instructions) {
      send({ type: 'error', error: `Agent "${agentName}" not found in global or project agents` });
      res.end();
      return;
    }

    // Inject output template if agent has one
    try {
      const agentPath = path.join(CLAUDE_DIR, 'agents', agentName + '.md');
      if (fs.existsSync(agentPath)) {
        const { data: agentMeta } = matter(fs.readFileSync(agentPath, 'utf-8'));
        if (agentMeta.output_template) {
          const tmplPath = path.join(TEMPLATES_DIR, agentMeta.output_template + '.md');
          if (fs.existsSync(tmplPath)) {
            const { content: tmplBody } = matter(fs.readFileSync(tmplPath, 'utf-8'));
            instructions += '\n\n## OUTPUT FORMAT (MANDATORY)\nYou MUST structure your response exactly as follows. Do not deviate from this format.\n\n' + tmplBody.trim();
          }
        }
      }
    } catch {}

    // Inject training corrections if any
    try {
      const agentKey = agentName.replace(/\s.*$/, '').toLowerCase();
      const trainingFiles = [agentName, agentKey].map(n => path.join(TRAINING_DIR, n + '.json'));
      for (const tf of trainingFiles) {
        if (fs.existsSync(tf)) {
          const corrections = JSON.parse(fs.readFileSync(tf, 'utf-8')).filter(c => c.status === 'active');
          if (corrections.length > 0) {
            instructions += '\n\n## TRAINING CORRECTIONS (Follow these strictly)\n' +
              corrections.map((c, i) => `${i + 1}. [${c.timestamp.split('T')[0]}] ${c.correction}`).join('\n');
          }
          break;
        }
      }
    } catch {}
  }

  if (customInstructions) {
    instructions = customInstructions;
  }

  let fullPrompt = '';
  if (instructions) {
    fullPrompt = `${instructions}\n\n---\n\n## Task:\n${userPrompt}\n\n---\n\nIMPORTANT: Produce the actual deliverable directly. Do NOT write meta-commentary. Output only the finished work product.`;
  } else {
    fullPrompt = userPrompt;
  }

  const timeout = Math.min(timeoutMs ?? 120000, 600000); // max 10 min, ?? avoids 0 becoming falsy
  const claudePath = process.env.CLAUDE_PATH || 'claude';
  const childEnv = { ...process.env, HOME: os.homedir() };
  delete childEnv.CLAUDECODE;
  const proc = spawn(claudePath, ['-p'], { env: childEnv });
  let fullOutput = '';
  let killed = false;
  let ended = false; // Guard against double res.end()

  const finish = () => {
    if (ended) return;
    ended = true;
    try { res.end(); } catch {}
  };

  const timer = setTimeout(() => {
    killed = true;
    proc.kill('SIGTERM');
    setTimeout(() => { try { proc.kill('SIGKILL'); } catch {} }, 5000);
  }, timeout);

  const playgroundStartTime = Date.now();
  send({ type: 'start', agent: agentName || 'custom' });

  proc.stdout.on('data', (data) => {
    if (ended) return;
    const chunk = data.toString();
    fullOutput += chunk;
    try { send({ type: 'chunk', content: chunk }); } catch {}
  });

  proc.stderr.on('data', (data) => {
    if (ended) return;
    const msg = data.toString().trim();
    if (msg) {
      try { send({ type: 'activity', message: msg }); } catch {}
    }
  });

  proc.on('close', (code) => {
    clearTimeout(timer);
    if (ended) return;
    const runSource = req.body.source || 'playground';
    if (killed) {
      send({ type: 'error', error: `Timed out after ${timeout / 1000}s` });
      logAgentRun({ agentName: agentName || 'custom', prompt: userPrompt, output: '', source: runSource, duration: Date.now() - playgroundStartTime, status: 'error', error: `Timed out after ${timeout / 1000}s` });
    } else if (code !== 0 && !fullOutput.trim()) {
      send({ type: 'error', error: `Process exited with code ${code}` });
      logAgentRun({ agentName: agentName || 'custom', prompt: userPrompt, output: '', source: runSource, duration: Date.now() - playgroundStartTime, status: 'error', error: `Process exited with code ${code}` });
    } else {
      send({ type: 'done', output: fullOutput.trim() });
      logAgentRun({ agentName: agentName || 'custom', prompt: userPrompt, output: fullOutput.trim(), source: runSource, duration: Date.now() - playgroundStartTime, status: 'success' });
    }
    finish();
  });

  proc.on('error', (err) => {
    clearTimeout(timer);
    if (ended) return;
    send({ type: 'error', error: err.message });
    finish();
  });

