const CLAIMS_PATH = path.join(__dirname, '..', 'claims.json');
const MODEL_ROUTING_PATH = path.join(__dirname, '..', 'model-routing.json');
const MAX_AGENT_RUNS = 1000;

// ── Agent Run Tracker — foundation for analytics ────────────────────────────
function loadAgentRuns() {
  try { if (fs.existsSync(AGENT_RUNS_PATH)) return JSON.parse(fs.readFileSync(AGENT_RUNS_PATH, 'utf-8')); } catch {} return [];
}
function saveAgentRuns(list) {
  atomicWriteJson(AGENT_RUNS_PATH, list.slice(0, MAX_AGENT_RUNS));
}

// Write queue prevents race conditions when parallel orchestration nodes
// call logAgentRun() concurrently — without this, the second write overwrites the first.
const agentRunsQueue = [];
let agentRunsWriting = false;

function flushAgentRunsQueue() {
  if (agentRunsWriting || agentRunsQueue.length === 0) return;
  agentRunsWriting = true;
  const batch = agentRunsQueue.splice(0);
  try {
    const runs = loadAgentRuns();
    runs.unshift(...batch);
    saveAgentRuns(runs);
  } catch (err) {
    console.error('[logAgentRun] Failed to persist batch:', err.message);
  }
  agentRunsWriting = false;
  if (agentRunsQueue.length > 0) flushAgentRunsQueue();
}
function estimateTokens(text) {
  return Math.ceil((text || '').length / 4);
}
function estimateCost(inputTokens, outputTokens) {
  return (inputTokens * 3 + outputTokens * 15) / 1_000_000;
}
function logAgentRun(entry) {
  const inputTokens = estimateTokens(entry.prompt || '');
  const outputTokens = estimateTokens(entry.output || '');
  const run = {
    id: Date.now().toString(36) + Math.random().toString(36).slice(2, 7),
    agentName: entry.agentName || 'unknown',
    prompt: (entry.prompt || '').slice(0, 200),
    source: entry.source || 'unknown',
    timestamp: new Date().toISOString(),
    duration: entry.duration || 0,
    status: entry.status || 'success',
    promptChars: (entry.prompt || '').length,
    outputChars: (entry.output || '').length,
    estimatedTokens: inputTokens + outputTokens,
    estimatedCost: estimateCost(inputTokens, outputTokens),
    error: entry.error || null,
    metadata: entry.metadata || {},
  };
  agentRunsQueue.push(run);
  flushAgentRunsQueue();

  // Auto-learn from every run (ruflo-inspired SONA pattern)
  try {
    recordLearning(run.agentName, entry.taskType || 'general', {
      success: run.status === 'success',
      duration: run.duration,
      tokens: run.estimatedTokens,
      cost: run.estimatedCost,
    });
  } catch (err) {
    console.error('[logAgentRun] Failed to record learning:', err.message);
  }

  return run;
}

// ── Schedules — cron-based agent runs ───────────────────────────────────────
function loadSchedules() {
  try { if (fs.existsSync(SCHEDULES_PATH)) return JSON.parse(fs.readFileSync(SCHEDULES_PATH, 'utf-8')); } catch {} return [];
}
function saveSchedules(list) {
  atomicWriteJson(SCHEDULES_PATH, list);
}

// ── Webhooks — external trigger endpoints ───────────────────────────────────
function loadWebhooks() {
  try { if (fs.existsSync(WEBHOOKS_PATH)) return JSON.parse(fs.readFileSync(WEBHOOKS_PATH, 'utf-8')); } catch {} return [];
}
function saveWebhooks(list) {
  atomicWriteJson(WEBHOOKS_PATH, list);
}

